+++ b/training/level-1/L1-026-semver-compare/compareSemver.mjs
@@ -0,0 +1,55 @@
+export function compareSemver(a, b) {
+  if (typeof a !== 'string' || typeof b !== 'string') {
+    throw new TypeError('Arguments must be strings');
+  }
+
+  const parse = (s) => {
+    const match = s.match(/^(\d+)\.(\d+)\.(\d+)(?:-([^\+]*))?/);
+    if (!match) {
+      throw new RangeError('Invalid SemVer string');
+    }
+    return {
+      major: parseInt(match[1], 10),
+      minor: parseInt(match[2], 10),
+      patch: parseInt(match[3], 10),
+      prerelease: match[4] || null
+    };
+  };
+
+  const pa = parse(a);
+  const pb = parse(b);
+
+  if (pa.major !== pb.major) return pa.major - pb.major;
+  if (pa.minor !== pb.minor) return pa.minor - pb.minor;
+  if (pa.patch !== pb.patch) return pa.patch - pb.patch;
+
+  // Prerelease comparison
+  if (!pa.prerelease && !pb.prerelease) return 0;
+  if (!pa.prerelease) return 1;
+  if (!pb.prerelease) return -1;
+
+  const compareIdent = (aId, bId) => {
+    const aNum = /^\d+$/.test(aId);
+    const bNum = /^\d+$/.test(bId);
+
+    if (aNum && bNum) {
+      return parseInt(aId, 10) - parseInt(bId, 10);
+    }
+    if (aNum) return -1;
+    if (bNum) return 1;
+    return aId < bId ? -1 : aId > bId ? 1 : 0;
+  };
+
+  const aIds = pa.prerelease.split('.');
+  const bIds = pb.prerelease.split('.');
+
+  const len = Math.max(aIds.length, bIds.length);
+  for (let i = 0; i < len; i++) {
+    if (i >= aIds.length) return -1;
+    if (i >= bIds.length) return 1;
+    const cmp = compareIdent(aIds[i], bIds[i]);
+    if (cmp !== 0) return cmp;
+  }
+
+  return 0;
+}

